// Import of required libraries
import { test, expect, SkyrampClient } from '@skyramp/skyramp';
import {
    createCollection,
    createCollectionMember,
    deleteCollection,
    deleteCollectionMember,
    getCollection,
    getCollectionMembers,
    transferCollection,
} from './skyrampUtils';

// Ids no collection and no user in the database can hold.
const UNKNOWN_COLLECTION_ID = 999999999;
const UNKNOWN_USER_ID = 999999999;

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const collectionName = `rejections-${Date.now()}`;

    const collectionsPostResponse = await createCollection(client, collectionName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const createdCollection = JSON.parse(collectionsPostResponse.responseBody).response;
    const collectionId = Number(createdCollection.id);
    const ownerUserId = Number(createdCollection.ownerId);
    expect(Number.isInteger(collectionId), 'the created collection carries a numeric id').toBe(true);

    try {
        // The accepted request the rejections below are measured against.
        const collectionsMembersGetResponse = await getCollectionMembers(client, collectionId);
        expect(collectionsMembersGetResponse.statusCode, 'status code').toBe(200);
        expect(JSON.parse(collectionsMembersGetResponse.responseBody).response,
            'a freshly created collection has no members').toEqual([]);

        // A collection id that is not a number.
        const membersGetResponse = await getCollectionMembers(client, "abc", 400);
        expect(membersGetResponse.statusCode, 'status code').toBe(400);
        expect(JSON.parse(membersGetResponse.responseBody).response, 'a collection id that is not a number')
            .toBe("Invalid collection ID.");

        // A collection id that names no collection.
        const collectionsMembersGet1Response = await getCollectionMembers(client, UNKNOWN_COLLECTION_ID, 404);
        expect(collectionsMembersGet1Response.statusCode, 'status code').toBe(404);
        expect(JSON.parse(collectionsMembersGet1Response.responseBody).response,
            'listing the members of a collection that does not exist').toBe("Collection not found.");

        // A method the members route does not serve.
        const collectionsMembersPatchResponse = await createCollectionMember(
            client, collectionId, { email: "no-such-user@example.com", role: "editor" }, 405, "PATCH",
        );
        expect(collectionsMembersPatchResponse.statusCode, 'status code').toBe(405);
        expect(JSON.parse(collectionsMembersPatchResponse.responseBody).response, 'PATCH on the members route')
            .toBe("Method not allowed.");

        // An invite with no email in the body.
        const collectionsMembersPostResponse = await createCollectionMember(client, collectionId, { role: "editor" }, 400);
        expect(collectionsMembersPostResponse.statusCode, 'status code').toBe(400);
        expect(JSON.parse(collectionsMembersPostResponse.responseBody).response, 'an invite that names no email')
            .toBe("email is required.");

        // An invite for an email address that belongs to no user.
        const collectionsMembersPost1Response = await createCollectionMember(
            client, collectionId, { email: "no-such-user@example.com", role: "viewer" }, 404,
        );
        expect(collectionsMembersPost1Response.statusCode, 'status code').toBe(404);
        expect(JSON.parse(collectionsMembersPost1Response.responseBody).response,
            'an invite for an address that belongs to no user').toBe("User not found.");

        // A removal with no userId query parameter.
        const collectionsMembersDeleteResponse = await deleteCollectionMember(client, collectionId, null, 400);
        expect(collectionsMembersDeleteResponse.statusCode, 'status code').toBe(400);
        expect(JSON.parse(collectionsMembersDeleteResponse.responseBody).response, 'a removal that names no user')
            .toBe("userId query param is required.");

        // The owner asking to remove themselves.
        const collectionsMembersDelete1Response = await deleteCollectionMember(client, collectionId, ownerUserId, 400);
        expect(collectionsMembersDelete1Response.statusCode, 'status code').toBe(400);
        expect(JSON.parse(collectionsMembersDelete1Response.responseBody).response, 'the owner removing themselves')
            .toBe("Owner cannot remove themselves.");

        // A method the transfer route does not serve.
        const transferGetResponse = await transferCollection(client, collectionId, {}, 405, "GET");
        expect(transferGetResponse.statusCode, 'status code').toBe(405);
        expect(JSON.parse(transferGetResponse.responseBody).response, 'GET on the transfer route')
            .toBe("Method not allowed.");

        // A transfer with no toUserId in the body.
        const transferPostResponse = await transferCollection(client, collectionId, { collectionId }, 400);
        expect(transferPostResponse.statusCode, 'status code').toBe(400);
        expect(JSON.parse(transferPostResponse.responseBody).response, 'a transfer that names no new owner')
            .toBe("toUserId is required.");

        // A transfer to a user who is not a member of the collection.
        const transferPost1Response = await transferCollection(client, collectionId, { toUserId: UNKNOWN_USER_ID }, 400);
        expect(transferPost1Response.statusCode, 'status code').toBe(400);
        expect(JSON.parse(transferPost1Response.responseBody).response, 'a transfer to someone who is not a member')
            .toBe("Transfer target must already be a member of the collection.");

        // A transfer against a collection id that names no collection.
        const transferPost2Response = await transferCollection(
            client, UNKNOWN_COLLECTION_ID, { toUserId: UNKNOWN_USER_ID }, 404,
        );
        expect(transferPost2Response.statusCode, 'status code').toBe(404);
        expect(JSON.parse(transferPost2Response.responseBody).response,
            'a transfer against a collection that does not exist').toBe("Collection not found.");

        // The collection is untouched by every one of them.
        const collectionsMembersGet2Response = await getCollectionMembers(client, collectionId);
        expect(collectionsMembersGet2Response.statusCode, 'status code').toBe(200);
        expect(JSON.parse(collectionsMembersGet2Response.responseBody).response, 'no rejected request added a member')
            .toEqual([]);
        const collectionsGetResponse = await getCollection(client, collectionId);
        expect(collectionsGetResponse.statusCode, 'status code').toBe(200);
        expect(Number(JSON.parse(collectionsGetResponse.responseBody).response.ownerId),
            'no rejected request moved the collection to another owner').toBe(ownerUserId);
    } finally {
        // Runs whether the assertions above pass or fail, so the collection this test created
        // is always removed.
        const collectionsCollectionsDeleteResponse = await deleteCollection(client, collectionId);
        expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    }
});
